"""Imagens embutidas (base64) do painel de Registro."""

from __future__ import annotations

import base64
import os

from .config import REGISTRATION_BANNER_PATH, REGISTRATION_LOGO_PATH, logger


# As imagens do Registro Medellín ficam embutidas neste próprio main.py.
# Assim você só precisa enviar este único arquivo para o Pterodactyl.
_REGISTRATION_BANNER_B64 = """"""


_REGISTRATION_LOGO_B64 = """"""


def ensure_embedded_registration_images() -> None:
    """Cria as imagens ao lado do main.py automaticamente se elas não existirem."""
    for path, encoded in (
        (REGISTRATION_BANNER_PATH, _REGISTRATION_BANNER_B64),
        (REGISTRATION_LOGO_PATH, _REGISTRATION_LOGO_B64),
    ):
        if os.path.isfile(path):
            continue
        try:
            with open(path, "wb") as image_file:
                image_file.write(base64.b64decode(encoded))
            logger.info("Imagem do registro criada automaticamente: %s", path)
        except OSError:
            logger.exception("Não foi possível criar a imagem embutida do registro: %s", path)
